code = code.replace(/from "os"/g, 'from "node:os"');
code = code.replace(/from "crypto"/g, 'from "node:crypto"');

// ── Remove interface blocks ──────────────────────────────────────────
// Handle nested braces by counting
let result = "";
let i = 0;
while (i < code.length) {
  const lineStart = (i === 0 || code[i - 1] === "\n");
  if (lineStart) {
    const rest = code.slice(i);
    const interfaceMatch = rest.match(/^(export\s+)?interface\s+\w+[^{]*\{/);
    if (interfaceMatch) {
      let j = i + interfaceMatch[0].length;
      let depth = 1;
      while (j < code.length && depth > 0) {
        if (code[j] === "{") depth++;
        else if (code[j] === "}") depth--;
        j++;
      }
      if (j < code.length && code[j] === "\n") j++;
      i = j;
      continue;
    }
  }
  result += code[i];
  i++;
}
code = result;

// ── Remove "as Type" casts ──────────────────────────────────────────
// Match "as" preceded by word char, ), ], or quote — NOT "import * as X"
code = code.replace(/([\w\)\]\"\'])\s+as\s+[A-Za-z]\w*(\[\])?/g, "$1");

// ── Remove Record<...> type annotations ──────────────────────────────
code = code.replace(/:\s*Record<[^>]+>/g, "");

// ── Remove function return type annotations ──────────────────────────
// ): Type {    or    ): void {    or    ): string | null {
code = code.replace(/\):\s*[A-Za-z]\w*(\[\])?\s*(\|[^{]*)?\s*\{/g, ") {");

// ── Remove param type annotations ────────────────────────────────────
// Match  word: Type  in parameter contexts (followed by , ) =)
// Simple types: string, number, boolean, any, void
code = code.replace(/(\w)\s*:\s*(string|number|boolean|any|void)(\[\])?\s*([,\)=])/g, "$1 $4");
// Complex types: UpperCaseWord (ScenarioMeta, GymResult, etc.)
code = code.replace(/(\w)\s*:\s*[A-Z]\w*(\[\])?\s*([,\)=])/g, "$1 $3");
// Union types with null/undefined: word: Type | null
code = code.replace(/(\w)\s*:\s*[A-Za-z]\w*\s*\|\s*(null|undefined)\s*([,\)=])/g, "$1 $3");
